<?php
namespace App\Services\Payment;
use App\Models\Order; use App\Models\PaymentTransaction; use App\Models\PaymentWebhookEvent; use App\Services\Coupons\CouponReservationService; use App\Services\Inventory\InventoryService; use App\Support\PaymentLogger; use App\Support\SensitiveDataRedactor; use Illuminate\Support\Facades\DB;
class PaymobWebhookService {
 private const HMAC_FIELDS=['amount_cents','created_at','currency','error_occured','has_parent_transaction','id','integration_id','is_3d_secure','is_auth','is_capture','is_refunded','is_standalone_payment','is_voided','order.id','owner','pending','source_data.pan','source_data.sub_type','source_data.type','success'];
 public function __construct(private CompletePaidOrderService $complete,private InventoryService $inventory,private CouponReservationService $coupons){}
 public function verify(array $payload,?string $received): bool { $secret=(string)config('services.paymob.hmac_secret'); if($secret===''||!$received)return false; $obj=(array)($payload['obj']??$payload); $parts=[];foreach(self::HMAC_FIELDS as $field){$parts[]=$this->stringify(data_get($obj,$field,''));}$expected=hash_hmac('sha512',implode('',$parts),$secret);return hash_equals(strtolower($expected),strtolower(trim($received))); }
 public function process(array $payload): array { $obj=(array)($payload['obj']??[]); $txId=(string)($obj['id']??''); $rawHash=hash('sha256',json_encode($payload,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE));$eventKey=hash('sha256','paymob|'.$txId.'|'.$rawHash); $event=PaymentWebhookEvent::firstOrCreate(['event_key'=>$eventKey],['gateway'=>'paymob','provider_transaction_id'=>$txId?:null,'payload_hash'=>$rawHash,'status'=>'received','payload'=>SensitiveDataRedactor::redact($payload)]); if($event->processed_at)return ['status'=>'duplicate'];
  $result=DB::transaction(function()use($obj,$txId,$event){$lockedEvent=PaymentWebhookEvent::whereKey($event->id)->lockForUpdate()->firstOrFail();if($lockedEvent->processed_at)return ['status'=>'duplicate'];$orderNumber=$obj['merchant_reference']??data_get($obj,'order.merchant_order_id')??data_get($obj,'order.special_reference')??data_get($obj,'payment_key_claims.extra.order_number')??data_get($obj,'extras.order_number');$order=null;if($orderNumber)$order=Order::where('order_number',(string)$orderNumber)->lockForUpdate()->first();if(!$order&&$txId){$p=PaymentTransaction::where(fn($q)=>$q->where('provider_transaction_id',$txId)->orWhere('provider_payment_id',$txId))->lockForUpdate()->first();$order=$p?->order()->lockForUpdate()->first();}if(!$order){$lockedEvent->update(['status'=>'ignored_unknown','processed_at'=>now()]);PaymentLogger::warning('Paymob webhook unknown order',['provider_transaction_id'=>$txId]);return ['status'=>'unknown'];}
   $payment=PaymentTransaction::where('order_id',$order->id)->where('gateway','paymob')->latest('id')->lockForUpdate()->first();if(!$payment)$payment=PaymentTransaction::create(['order_id'=>$order->id,'payment_method_id'=>$order->payment_method_id,'gateway'=>'paymob','status'=>'pending','original_amount'=>$order->total_amount,'original_currency'=>$order->currency?:config('commerce.base_currency','EGP'),'idempotency_key'=>'PAYMOB-LEGACY-'.$order->id]);
   $expectedCents=(int)round(((float)$order->total_amount)*100);$actualCents=(int)($obj['amount_cents']??-1);$currency=strtoupper((string)($obj['currency']??''));$expectedCurrency=strtoupper((string)($order->currency?:$payment->original_currency?:config('services.paymob.currency','EGP')));$integration=(string)($obj['integration_id']??'');$expectedIntegration=(string)config('services.paymob.integration_id');$mismatch=[];if($actualCents!==$expectedCents)$mismatch[]='amount';if($currency!==$expectedCurrency)$mismatch[]='currency';if($expectedIntegration!==''&&$integration!==$expectedIntegration)$mismatch[]='integration';if($mismatch){$payment->forceFill(['status'=>'manual_review','provider_status'=>'mismatch','provider_transaction_id'=>$txId?:$payment->provider_transaction_id,'provider_payment_id'=>$txId?:$payment->provider_payment_id,'requires_manual_review'=>true,'failure_reason'=>'Webhook mismatch: '.implode(',',$mismatch),'last_webhook_payload'=>SensitiveDataRedactor::redact($obj)])->save();$lockedEvent->update(['order_id'=>$order->id,'payment_transaction_id'=>$payment->id,'status'=>'manual_review','processed_at'=>now()]);PaymentLogger::warning('Paymob webhook rejected by reconciliation',['order_id'=>$order->id,'mismatch'=>$mismatch]);return ['status'=>'manual_review'];}
   $success=(bool)($obj['success']??false);$pending=(bool)($obj['pending']??false);$voided=(bool)($obj['is_voided']??false);$refunded=(bool)($obj['is_refunded']??false);$paid=$success&&!$pending&&!$voided&&!$refunded; $newStatus=$paid?'paid':($pending?'pending':'failed');$payment->forceFill(['status'=>$newStatus,'provider_status'=>$newStatus,'provider_transaction_id'=>$txId?:$payment->provider_transaction_id,'provider_payment_id'=>$txId?:$payment->provider_payment_id,'last_webhook_payload'=>SensitiveDataRedactor::redact($obj),'webhook_processed_at'=>now(),'paid_at'=>$paid?($payment->paid_at?:now()):$payment->paid_at,'failed_at'=>!$paid&&!$pending?($payment->failed_at?:now()):$payment->failed_at])->save();$order->forceFill(['transaction_id'=>$txId?:$order->transaction_id,'status_payment'=>$newStatus,'payment_state'=>$newStatus,'paid_at'=>$paid?($order->paid_at?:now()):$order->paid_at])->save();$lockedEvent->update(['order_id'=>$order->id,'payment_transaction_id'=>$payment->id,'status'=>$newStatus,'processed_at'=>now()]);return ['status'=>$newStatus,'order_id'=>$order->id];},3);
  if(($result['status']??null)==='paid'){$order=Order::find($result['order_id']);if($order)$this->complete->complete($order);}elseif(in_array($result['status']??'', ['failed','expired'],true)){$order=Order::find($result['order_id']);if($order){$this->inventory->releaseOrder($order,'payment_'.$result['status']); app(\App\Services\Fulfillment\LocalSerialFulfillmentService::class)->releaseOrder($order,'payment_'.$result['status']); $this->coupons->release($order);}} return $result;
 }
 private function stringify(mixed $v): string {if(is_bool($v))return $v?'true':'false';if($v===null)return '';return (string)$v;}
}
